import axios from "axios";

// Base URL (you can switch to env variable for flexibility)
const API_BASE =
  process.env.REACT_APP_API_URL || "http://localhost:5000/api";

// Create axios instance
const API = axios.create({
  baseURL: API_BASE,
  timeout: 10000, // ⏱️ set timeout (10s)
  headers: {
    "Content-Type": "application/json",
  },
});

// Interceptor for debugging (optional)
API.interceptors.response.use(
  (response) => response,
  (error) => {
    console.error("API Error:", error?.response || error.message);
    return Promise.reject(error);
  }
);

// ------------------ API Functions ------------------

// Fetch all incidents with filters/pagination
export const fetchIncidents = (params) =>
  API.get("/incidents", { params });

// Fetch incident by ID
export const fetchIncidentById = (id) => API.get(`/incidents/${id}`);

// Create a new incident
export const createIncident = (data) => API.post("/incidents", data);

// Update incident status
export const updateIncidentStatus = (id, status) =>
  API.patch(`/incidents/${id}/status`, { status });

// Add a comment to an incident
export const addIncidentComment = (id, text) =>
  API.post(`/incidents/${id}/comments`, { text });
